create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, company_name text, phone text, preferred_language text default 'en', role text default 'owner', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.prospects (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, first_name text, last_name text, business_name text, phone text, email text, preferred_language text default 'en', source text, service_interest text, stage text, estimated_value numeric default 0, ai_score integer, priority text, interest_level text, next_follow_up timestamptz, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.prospect_notes (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, prospect_id uuid not null references public.prospects(id) on delete cascade, content text not null, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.activities (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, prospect_id uuid references public.prospects(id) on delete cascade, type text, description text, metadata jsonb default '{}'::jsonb, created_at timestamptz default now());
create table public.follow_ups (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, prospect_id uuid not null references public.prospects(id) on delete cascade, title text, due_at timestamptz, status text default 'open', priority text, created_at timestamptz default now(), completed_at timestamptz);
create table public.tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, prospect_id uuid references public.prospects(id) on delete cascade, title text not null, description text, due_at timestamptz, priority text, status text default 'open', source text, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.communications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, prospect_id uuid references public.prospects(id) on delete cascade, channel text, direction text, subject text, content text, status text, provider text, created_at timestamptz default now(), sent_at timestamptz);
create table public.communication_drafts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, prospect_id uuid references public.prospects(id) on delete cascade, channel text, recipient text, subject text, content text, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.automation_rules (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text, active boolean default true, trigger_type text, condition jsonb default '{}'::jsonb, action_type text, action_config jsonb default '{}'::jsonb, last_run_at timestamptz, times_triggered integer default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.automation_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, rule_id uuid references public.automation_rules(id) on delete cascade, prospect_id uuid references public.prospects(id) on delete set null, action text, result text, created_at timestamptz default now());
create table public.message_templates (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text, category text, language text, channel text, content text, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.services (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text, category text, default_price numeric, description text, active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.sales_goals (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, month date, revenue_goal numeric, deals_goal integer, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.ai_results (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, prospect_id uuid references public.prospects(id) on delete cascade, type text, result jsonb default '{}'::jsonb, provider text, generated_at timestamptz default now());
